import {mergeScreenshotData} from './screenshot-data.mjs';
import {categories,colors,day,dateOf,plus,distance,monday,relative,createTask,active,score,complete,reopen,weekly} from './model.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='daybook.notebook.v1';let state={version:1,tasks:[]},view='today',area='',sort='newest',weekOffset=0,editing=null,toastTimer,storageBlocked=false;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(parsed.version!==1||!Array.isArray(parsed.tasks))throw Error('Unsupported notebook');state=parsed}}catch(e){storageBlocked=true;$('#save-status').textContent='Could not load notebook — existing data kept';$('#save-status').classList.add('storage-error')}
if(!storageBlocked){try{const imported=mergeScreenshotData(state);if(imported!==state){localStorage.setItem(KEY,JSON.stringify(imported));state=imported}}catch(e){storageBlocked=true;$('#save-status').textContent='Screenshot import could not be saved — reload to retry';$('#save-status').classList.add('storage-error')}}
function save(tasks){if(storageBlocked){notify('Notebook could not load. Back up the stored data before using a new browser.');return false}try{const next={...state,version:1,tasks};localStorage.setItem(KEY,JSON.stringify(next));state=next;$('#save-status').textContent='Saved on this device';$('#save-status').classList.remove('storage-error');render();return true}catch(e){$('#save-status').textContent='Not saved — storage unavailable';$('#save-status').classList.add('storage-error');notify('Couldn’t save. Your task input is still here. Free up browser storage and try again.');return false}}
function notify(text,action){clearTimeout(toastTimer);$('#toast').hidden=false;$('#toast').innerHTML=esc(text)+(action?'<button id="undo-button">Undo</button>':'');if(action)$('#undo-button').onclick=action;toastTimer=setTimeout(()=>$('#toast').hidden=true,7000)}
function options(){return categories.map(c=>`<option>${esc(c)}</option>`).join('')}
$('#task-category').innerHTML=options();$('#task-category').value='Personal';$('#edit-form [name="category"]').innerHTML=options();
function taskMeta(t){return `<span class="area-label"><i class="category-dot" style="background:${colors[categories.indexOf(t.category)]||colors[4]}"></i>${esc(t.category)}</span>${t.due?`<span class="meta-separator">·</span><span class="due ${t.due<day()&&!t.completedAt?'overdue':''}" title="${esc(t.due)}">${t.completedAt?'Due '+esc(dateOf(t.due).toLocaleDateString(undefined,{month:'short',day:'numeric'})):esc(relative(t.due))}</span>`:''}${t.repeat!=='none'?`<span class="meta-separator">·</span><span>↻ ${t.repeat==='daily'?'Everyday':'Weekly'}</span>`:''}${t.effort?`<span class="meta-separator">·</span><span>${t.effort} min</span>`:''}${t.sourceHint&&!t.due?`<span class="meta-separator">·</span><span>${esc(t.sourceHint)}</span>`:''}${!t.completedAt&&!t.unknownCreatedAt&&distance(day(),day(new Date(t.createdAt)))>1?`<span class="meta-separator">·</span><span>Added ${distance(day(),day(new Date(t.createdAt)))}d ago</span>`:''}`}
function row(t,done=false){const future=t.available&&t.available>day();return `<div class="task-row" data-id="${esc(t.id)}"><button class="check ${done?'completed':''}" data-action="${done?'reopen':'complete'}" data-id="${esc(t.id)}" aria-label="${done?'Reopen':'Complete'} ${esc(t.title)}" ${!done&&future?'disabled title="Available on '+esc(t.available)+'"':''}><span>${done?'✓':''}</span></button><div class="task-content"><div class="task-name">${esc(t.title)}</div><div class="task-meta">${taskMeta(t)}</div></div>${done?`<span class="task-meta">${t.dateOnlyCompletion?'From Notes':new Date(t.completedAt).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</span>`:`<button class="edit-task" data-action="edit" data-id="${esc(t.id)}" aria-label="Edit ${esc(t.title)}">···</button>`}</div>`}
function empty(title,text){return `<div class="empty"><div class="empty-mark" aria-hidden="true">—</div><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`}
function chart(days){const max=Math.max(1,...days.map(d=>d.count));return days.map(d=>`<div class="bar-column ${d.date===day()?'today':''}" aria-label="${esc(dateOf(d.date).toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'}))}: ${d.count} completed"><span class="bar-value">${d.count||' '}</span><div class="bar-track"><div class="bar" style="height:${Math.max(3,d.count/max*100)}%"></div></div><span class="bar-day">${dateOf(d.date).toLocaleDateString(undefined,{weekday:'short'}).slice(0,1)}</span></div>`).join('')}
function render(){const open=active(state.tasks),doneToday=state.tasks.filter(t=>t.completedAt&&!t.deletedAt&&day(new Date(t.completedAt))===day());$('#date-heading').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'});$('#nav-count').textContent=open.length;$('#categories').innerHTML=categories.map((c,i)=>`<button class="category ${area===c?'active':''}" data-category="${esc(c)}"><i class="category-dot" style="background:${colors[i]}"></i>${esc(c.split(' / ')[0])}<span class="category-count">${open.filter(t=>t.category===c).length||'—'}</span></button>`).join('');
const filtered=open.filter(t=>!area||t.category===area);filtered.sort(sort==='suggested'?(a,b)=>score(b)-score(a):sort==='due'?(a,b)=>(a.due||'9999').localeCompare(b.due||'9999'):(a,b)=>b.createdAt.localeCompare(a.createdAt));$('#list-title').innerHTML=`${area?esc(area.split(' / ')[0].toUpperCase()):'TO DO'} <span id="list-count">${filtered.length}</span>`;$('#task-list').innerHTML=filtered.length?filtered.map(t=>row(t)).join(''):empty(area?'A little breathing room.':'A fresh page.','Add your first task above. A class assignment, one LeetCode problem, whatever’s on your mind.');$('#today-done').innerHTML=`<div class="section-heading"><h2>DAY DONE · TODAY <span>${doneToday.length}</span></h2><button class="text-button" data-view="history">View history ↗</button></div>${doneToday.length?doneToday.filter(t=>!area||t.category===area).map(t=>row(t,true)).join(''):'<p class="help">A place for every little win. Check off a task to start.</p>'}`;
const candidate=open.filter(t=>(!t.available||t.available<=day())&&(!area||t.category===area)).sort((a,b)=>score(b)-score(a))[0];$('#suggestion').innerHTML=candidate?`<h3>${esc(candidate.title)}</h3><p>${candidate.due?esc(relative(candidate.due))+' · ':''}${esc(candidate.category.split(' / ')[0])}${candidate.effort?' · '+candidate.effort+' min':''}</p><p style="margin-top:12px">${candidate.due&&candidate.due<=day()?'A deadline worth making room for.':candidate.importance===3?'One of the things you marked important.':'One small step to get moving.'}</p><button class="text-button" data-action="complete" data-id="${esc(candidate.id)}">Mark done ✓</button>`:'<h3>What’s on your mind?</h3><p>Add a task to find your next small step. Deadlines and importance will help it rise to the top.</p>';
const w=weekly(state.tasks,monday());$('#week-total').textContent=w.done.length;$('#mini-chart').innerHTML=chart(w.days);$('#week-caption').textContent=w.done.length?`${w.days.filter(d=>d.count>0).length} ${w.days.filter(d=>d.count>0).length===1?'day':'days'} with something done. It all counts.`:'Your week takes shape as you check things off.';
renderHistory();renderWeek();renderReferences();}
function renderReferences(){$('#notes-view').innerHTML='<p class="history-intro">Imported from your Notes screenshots. Task lists and dated history are in My day and Day done.</p>'+state.references.map(n=>`<section class="panel reference-note"><h2>${esc(n.title)}</h2><p>${esc(n.description)}</p><ul>${n.items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul></section>`).join('')}
function renderHistory(){const completed=state.tasks.filter(t=>t.completedAt&&!t.deletedAt&&(!area||t.category===area)).sort((a,b)=>b.completedAt.localeCompare(a.completedAt));const groups=Map.groupBy?Map.groupBy(completed,t=>day(new Date(t.completedAt))):completed.reduce((m,t)=>{const d=day(new Date(t.completedAt));m.set(d,[...(m.get(d)||[]),t]);return m},new Map());$('#history-view').innerHTML=`<p class="history-intro">The things you did, kept for you. Click a check to move a task back to your list.</p>${completed.length?[...groups].map(([date,tasks])=>`<section class="history-day"><h2>DAY DONE · ${esc(dateOf(date).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}).toUpperCase())}<span>${tasks.length} completed</span></h2>${tasks.map(t=>row(t,true)).join('')}</section>`).join(''):empty('Your wins will live here.','Complete a task and it will move here automatically, under the day you finished it.')}`}
function renderWeek(){const start=plus(monday(),weekOffset*7),w=weekly(state.tasks,start),prior=weekly(state.tasks,plus(start,-7)),end=plus(start,6),current=weekOffset===0;const peak=w.days.filter(d=>d.date<=day()).sort((a,b)=>b.count-a.count)[0];const pile=w.days.filter(d=>d.backlog!==null).sort((a,b)=>b.backlog-a.backlog)[0];const notes=[];if(state.imports?.length)notes.push('Screenshot history is partial. Task creation dates and missing days weren’t recorded, so earlier workload counts are incomplete.');if(w.done.length){notes.push(`${dateOf(peak.date).toLocaleDateString(undefined,{weekday:'long'})} has the most completions (${peak.count}). That records output, not how hard each task was.`);if(prior.done.length)notes.push(`${w.done.length} completed ${current?'so far this week':'this week'}, compared with ${prior.done.length} in the full previous week.`)}else notes.push('There are no completions for this week yet. Check off tasks to begin seeing your patterns.');if(w.overdue.length)notes.push(`${w.overdue.length} task${w.overdue.length===1?' is':'s are'} overdue ${current?'now':'at week’s end'}. Try breaking the oldest one into a smaller next step or choosing a realistic new date.`);if(pile?.backlog)notes.push(`Open work peaked at ${pile.backlog} task${pile.backlog===1?'':'s'} on ${dateOf(pile.date).toLocaleDateString(undefined,{weekday:'long'})}. Move a flexible task away from that day if it felt crowded.`);notes.push('A quiet day can be a rest day. A few weeks of records will give a clearer picture.');
$('#week-view').innerHTML=`<div class="review-nav"><button id="prev-week" aria-label="Previous week">←</button><strong>${dateOf(start).toLocaleDateString(undefined,{month:'short',day:'numeric'})} – ${dateOf(end).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</strong><button id="next-week" aria-label="Next week" ${current?'disabled':''}>→</button>${!current?'<button class="text-button" id="current-week">This week</button>':''}</div><div class="stats"><div class="stat"><span>Tasks completed</span><strong>${w.done.length}</strong></div><div class="stat"><span>Days with completions</span><strong>${w.days.filter(d=>d.count).length}<small style="font-size:16px;color:var(--muted)"> / 7</small></strong></div><div class="stat"><span>${current?'Open now':'Open at week’s end'}</span><strong>${w.unfinished.length}</strong></div><div class="stat"><span>${current?'Overdue now':'Overdue at week’s end'}</span><strong class="${w.overdue.length?'overdue':''}">${w.overdue.length}</strong></div></div><div class="review-grid"><div><section class="panel"><h2>A week of small wins</h2><p>Tasks completed each day · Monday–Sunday</p><div class="mini-chart">${chart(w.days)}</div><div class="area-breakdown">${categories.map((c,i)=>{const n=w.done.filter(t=>t.category===c).length;return `<div class="area-progress"><span>${esc(c.split(' / ')[0])}</span><div class="progress-track"><span style="width:${w.done.length?n/w.done.length*100:0}%;background:${colors[i]}"></span></div><span>${n}</span></div>`}).join('')}</div><p style="margin:25px 0 0">${w.minutes?`${w.minutes} minutes of estimated effort completed. Estimates aren’t tracked time.`:'Add optional effort estimates to see the size of the work you finish.'}</p></section><section class="panel" style="margin-top:24px"><h2>Where work collected</h2><p>Open tasks at the end of each day. Today’s count is live; future days stay blank.</p><table class="backlog-table"><thead><tr><th>Day</th><th>Added</th><th>Done</th><th>Left open</th></tr></thead><tbody>${w.days.map(d=>`<tr><td>${dateOf(d.date).toLocaleDateString(undefined,{weekday:'short'})}${d.date===day()?' (today)':''}</td><td>${d.date>day()?'—':d.added}</td><td>${d.date>day()?'—':d.count}</td><td>${d.backlog??'—'}</td></tr>`).join('')}</tbody></table></section></div><div><section class="panel"><h2>A few things to notice</h2><ul class="observations">${notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></section><section class="panel" style="margin-top:24px"><h2>${current?'Still on your list':'Still open at week’s end'}</h2><p>${w.unfinished.length} unfinished · ${w.overdue.length} overdue. Future repeats aren’t included.</p>${w.unfinished.length?w.unfinished.sort((a,b)=>score(b)-score(a)).map(t=>`<div style="padding:12px 0;border-bottom:1px solid var(--line);font-size:13px">${esc(t.title)}<div class="task-meta">${esc(t.category.split(' / ')[0])}${t.due?' · Due '+esc(dateOf(t.due).toLocaleDateString(undefined,{month:'short',day:'numeric'})):''}</div></div>`).join(''):'<p>No unfinished tasks recorded for this week.</p>'}</section></div></div>`;
$('#prev-week').onclick=()=>{weekOffset--;renderWeek()};$('#next-week').onclick=()=>{weekOffset=Math.min(0,weekOffset+1);renderWeek()};if($('#current-week'))$('#current-week').onclick=()=>{weekOffset=0;renderWeek()}}
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
function navigate(next){view=['today','history','week','notes'].includes(next)?next:'today';const names={today:'My day',history:'Day done',week:'Weekly review',notes:'Reference notes'};['today','history','week','notes'].forEach(v=>$('#'+v+'-view').hidden=v!==view);document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});$('#page-title').innerHTML=names[view]+'<span class="title-dot">.</span>';$('#breadcrumb').innerHTML='Notebook <span>/</span> '+names[view];$('#page-note').textContent={today:'A little less in your head.',history:'You did more than you think.',week:'A moment to look back.',notes:'Kept from your notebook.'}[view];history.replaceState(null,'','#'+view);}
$('#details-toggle').onclick=()=>{const hidden=!$('#task-details').hidden;$('#task-details').hidden=hidden;$('#details-toggle').setAttribute('aria-expanded',String(!hidden));$('#details-toggle').innerHTML=hidden?'Add details <span>＋</span>':'Less detail <span>−</span>'};
$('#task-form').onsubmit=e=>{e.preventDefault();try{const task=createTask(Object.fromEntries(new FormData(e.target)));if(save([task,...state.tasks])){e.target.reset();$('#task-category').value=area||'Personal';sort='newest';$('#sort').value='newest';render();$('#task-title').focus();notify('Task added to the top.')}}catch(e){notify(e.message)}};
$('#sort').onchange=e=>{sort=e.target.value;render()};
function finish(id){try{const prior=state.tasks;if(save(complete(prior,id))){notify('Moved to Day done.',()=>{try{if(save(reopen(state.tasks,id)))notify('Task restored.')}catch(e){notify(e.message)}})}}catch(e){notify(e.message)}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-view]');if(nav){area='';navigate(nav.dataset.view);render();return}const cat=e.target.closest('[data-category]');if(cat){area=area===cat.dataset.category?'':cat.dataset.category;$('#task-category').value=area||'Personal';navigate('today');render();return}const shortcut=e.target.closest('[data-due]');if(shortcut){$('#task-due').value=shortcut.dataset.due==='none'?'':plus(day(),Number(shortcut.dataset.due));return}const action=e.target.closest('[data-action]');if(!action)return;const {id}=action.dataset;if(action.dataset.action==='complete')finish(id);else if(action.dataset.action==='reopen'){try{if(save(reopen(state.tasks,id)))notify('Moved back to your list.')}catch(e){notify(e.message)}}else{editing=id;const t=state.tasks.find(t=>t.id===id);const f=$('#edit-form');for(const key of ['title','category','due','importance','repeat','effort'])f.elements[key].value=t[key]??'';$('#edit-dialog').showModal()}});
$('#close-dialog').onclick=()=>$('#edit-dialog').close();$('#edit-form').onsubmit=e=>{e.preventDefault();try{const old=state.tasks.find(t=>t.id===editing);const updated=createTask(Object.fromEntries(new FormData(e.target)));const value={...old,...updated,sourceHint:updated.due?'':old.sourceHint,id:old.id,createdAt:old.createdAt,parentId:old.parentId,available:updated.repeat!=='none'&&old.available>day()?updated.due:''};if(save(state.tasks.map(t=>t.id===editing?value:t))){$('#edit-dialog').close();notify('Task updated.')}}catch(e){notify(e.message)}};
$('#delete-task').onclick=()=>{const deletedId=editing;const prior=state.tasks;if(save(prior.map(t=>t.id===deletedId?{...t,deletedAt:new Date().toISOString()}:t))){$('#edit-dialog').close();notify('Task deleted.',()=>{if(save(state.tasks.map(t=>t.id===deletedId?{...t,deletedAt:null}:t)))notify('Task restored.')})}};
$('#export-button').onclick=()=>{const raw=storageBlocked?localStorage.getItem(KEY):JSON.stringify(state,null,2);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([raw||''],{type:'application/json'}));a.download='daybook-'+day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=JSON.parse(e.newValue);if(next?.version===1&&Array.isArray(next.tasks)){state=next;render()}}catch{notify('Another tab changed the notebook. Reload to continue.')}}});let lastDay=day();setInterval(()=>{if(lastDay!==day()){lastDay=day();render()}},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)render()});navigate(location.hash.slice(1));render();
if(document.modelContext?.registerTool){for(const tool of [{name:'list_tasks',description:'Read this browser’s open Daybook tasks.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({tasks:active(state.tasks)})},{name:'add_task',description:'Create a personal task at the top of Daybook.',inputSchema:{type:'object',properties:{title:{type:'string'},due:{type:'string'},category:{type:'string',enum:categories}},required:['title'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const t=createTask(input);if(!save([t,...state.tasks]))throw Error('Task could not be saved');return {id:t.id,title:t.title}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
